def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    pieces = []
    # 2x2 square pieces are color 1.
    for r in range(h - 1):
        for c in range(w - 1):
            cells = frozenset((r + dr, c + dc) for dr in range(2) for dc in range(2))
            if cells <= occupied:
                pieces.append((cells, 1))

    # L triomino colors encode the missing corner of their 2x2 bounding box.
    missing_color = {(0, 0): 2, (1, 0): 3, (0, 1): 4, (1, 1): 2}
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
            for mr, mc in missing_color:
                cells = frozenset(square - {(r + mr, c + mc)})
                if cells <= occupied:
                    pieces.append((cells, missing_color[(mr, mc)]))

    by_cell = {p: [] for p in occupied}
    for cells, color in pieces:
        for p in cells:
            by_cell[p].append((cells, color))

    def solve(left):
        if not left:
            return []
        p = min(left, key=lambda x: sum(1 for cells, _ in by_cell[x] if cells <= left))
        for cells, color in by_cell[p]:
            if cells <= left:
                rest = solve(left - cells)
                if rest is not None:
                    return [(cells, color)] + rest
        return None

    solution = solve(occupied)
    if solution:
        for cells, color in solution:
            for r, c in cells:
                out[r][c] = color
    return out
